bool StructTraits<::ai_chat::mojom::YoutubeInnerTubeConfig::DataView, ::ai_chat::mojom::YoutubeInnerTubeConfigPtr>::Read(
    ::ai_chat::mojom::YoutubeInnerTubeConfig::DataView input,
    ::ai_chat::mojom::YoutubeInnerTubeConfigPtr* output) {
  bool success = true;
  ::ai_chat::mojom::YoutubeInnerTubeConfigPtr result(::ai_chat::mojom::YoutubeInnerTubeConfig::New());
  
      if (success && !input.ReadApiKey(&result->api_key))
        success = false;
      if (success && !input.ReadVideoId(&result->video_id))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::ai_chat::mojom::PageContent::DataView, ::ai_chat::mojom::PageContentPtr>::Read(
    ::ai_chat::mojom::PageContent::DataView input,
    ::ai_chat::mojom::PageContentPtr* output) {
  bool success = true;
  ::ai_chat::mojom::PageContentPtr result(::ai_chat::mojom::PageContent::New());
  
      if (success && !input.ReadContent(&result->content))
        success = false;
      if (success && !input.ReadType(&result->type))
        success = false;
  *output = std::move(result);
  return success;
}

// static
bool UnionTraits<::ai_chat::mojom::PageContentData::DataView, ::ai_chat::mojom::PageContentDataPtr>::Read(
    ::ai_chat::mojom::PageContentData::DataView input,
    ::ai_chat::mojom::PageContentDataPtr* output) {
  using UnionType = ::ai_chat::mojom::PageContentData;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kContent: {
      std::string result_content{};
      if (!input.ReadContent(&result_content))
        return false;

      *output = UnionType::NewContent(
          std::move(result_content));
      break;
    }
    case Tag::kContentUrl: {
      ::GURL result_content_url{};
      if (!input.ReadContentUrl(&result_content_url))
        return false;

      *output = UnionType::NewContentUrl(
          std::move(result_content_url));
      break;
    }
    case Tag::kYoutubeInnerTubeConfig: {
      ::ai_chat::mojom::YoutubeInnerTubeConfigPtr result_youtube_inner_tube_config{};
      if (!input.ReadYoutubeInnerTubeConfig(&result_youtube_inner_tube_config))
        return false;

      *output = UnionType::NewYoutubeInnerTubeConfig(
          std::move(result_youtube_inner_tube_config));
      break;
    }
    default:

      return false;
  }
  return true;
}

